import csv, json, sys
d = sys.argv[1]
for l in open(d + "/blocks.jsonl"):
    b = json.loads(l); print(f"{b['block']:9s} {b['seconds']:5.1f}s swapin={b['host_window']['swap_in_bytes']/2**20:5.0f}MiB maxP={b['host_window']['max_pressure_level']}")
